"use strict";(globalThis.webpackChunk_picteus_docs=globalThis.webpackChunk_picteus_docs||[]).push([[3510],{2467(e,t,a){a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>o,metadata:()=>n,toc:()=>c});const n=JSON.parse('{"id":"vision","title":"Vision","description":"Picteus is best understood as an extensible, local-first platform for managing, transforming, and understanding image","source":"@site/docs/vision.md","sourceDirName":".","slug":"/vision","permalink":"/picteus/docs/vision","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"visionSidebar"}');var i=a(4848),s=a(8453);const o={},r="Vision",l={},c=[{value:"What Picteus aims to become",id:"what-picteus-aims-to-become",level:2},{value:"Collaboration with local and remote AI systems",id:"collaboration-with-local-and-remote-ai-systems",level:2},{value:"A platform for industrialized image work",id:"a-platform-for-industrialized-image-work",level:2},{value:"API-first and UX-first",id:"api-first-and-ux-first",level:2},{value:"Normalized entities and formal contracts",id:"normalized-entities-and-formal-contracts",level:2},{value:"Extensions as the path to adaptability",id:"extensions-as-the-path-to-adaptability",level:2},{value:"A user-specific platform, not a one-fits-all product",id:"a-user-specific-platform-not-a-one-fits-all-product",level:2},{value:"The direction of the ecosystem",id:"the-direction-of-the-ecosystem",level:2},{value:"Why the vision is realistic now",id:"why-the-vision-is-realistic-now",level:2},{value:"Closing view",id:"closing-view",level:2}];function d(e){const t={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"vision",children:"Vision"})}),"\n",(0,i.jsx)(t.p,{children:"Picteus is best understood as an extensible, local-first platform for managing, transforming, and understanding image\nassets at scale. It is not merely a gallery or a search tool. It is a system for turning a collection of images into a\nstructured asset corpus that can be processed, enriched, explored, and reproduced with software and AI services."}),"\n",(0,i.jsx)(t.p,{children:"At its core, Picteus treats images as first-class entities with a rich and extensible set of metadata facets: built-in\nmetadata, tags, structured features, and vector embeddings. These facets make it possible to search visually,\nsemantically, and analytically. The platform also gives a place for generation lineage and provenance to live: the\nrecipes, transformations, and relationships that created an asset can be captured and revisited over time."}),"\n",(0,i.jsx)(t.p,{children:"This gives Picteus a role similar to a local platform for image operations and knowledge management \u2014 a kind of mini\noperating system for image assets. It is designed to coordinate multiple tools and services around the same corpus:\nlocal AI models, remote inference providers, automation pipelines, custom extraction routines, and user-defined\nworkflows."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"what-picteus-aims-to-become",children:"What Picteus aims to become"}),"\n",(0,i.jsx)(t.p,{children:"Picteus sits at the intersection of three needs that many teams now face:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"the need to manage large image collections with structure and traceability ;"}),"\n",(0,i.jsx)(t.li,{children:"the need to collaborate with AI systems that generate, classify, annotate, and transform images ;"}),"\n",(0,i.jsx)(t.li,{children:"the need to adapt the software itself to the user's own workflows instead of forcing all users into a single rigid\ninterface."}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"In practice, the platform is designed to operate as a durable image asset environment: a place where new images are\ningested, processed, annotated, searched, and transformed while preserving their history and relations. It supports the\ncreation of a rich corpus of connected artifacts rather than a flat bucket of files."}),"\n",(0,i.jsx)(t.p,{children:"This is especially relevant in AI-generated image workflows. A generated image is often not just a final render; it is\nthe result of a prompt, a recipe, parameters, models, tools, and transformations. Picteus can capture that context,\norganize it, and give it a stable structure. In other words, it can behave much like a genealogist for generated images:\nit traces parentage, recombinations, and derivations, and it makes it possible to understand how a result was produced\nand how it evolved."}),"\n",(0,i.jsx)(t.p,{children:"The capture of the generation instructions \u2014 the recipe \u2014 is not a cosmetic detail. It is a core part of accountability\nand traceability. It helps identify how an AI-generated image was built, which models and parameters were used, which\nsource assets were injected or transformed, and which steps were applied before the final result was reached. This\nmatters for authorship and provenance, especially when source inputs may be subject to copyright, licensing constraints,\nor commercial obligations. Being able to reconstruct the process helps protect the authors, makes rightsholders more\nconfident, and can contribute to a healthier financial equation by clarifying what was created, what was reused, and\nwhat was transformed."}),"\n",(0,i.jsx)(t.p,{children:"The same logic applies to the broader image lifecycle: an image may start as a capture, become a synthetic render, be\ntransformed by an external tool, be enriched with tags and features, and be compared with related artifacts through\nsemantic search. Picteus provides a framework for making that lifecycle explicit and navigable."}),"\n",(0,i.jsx)(t.p,{children:"This is also where the idea of a git-like history becomes highly relevant. A generated image should not be treated as a\nstandalone artifact with no memory. It should be seen as a node in a revision graph \u2014 a lineage where each derived asset\ncan be traced back to its parents, its recipe, and the transformations applied over time. Picteus helps creators account\nfor the process they went through, preserving a history that may eventually prove invaluable when facing legislation,\ncompliance, usage audits, or disputes about how a result was produced. In other words, Picteus aims to make the\ngenealogy of generated images explicit and reviewable, much like a version-control system records the evolution of code."}),"\n",(0,i.jsx)(t.p,{children:"The vision is to make capturing those assets easy regardless of the service or software that generated them. Whether an\nimage comes from a local user interface, a desktop application, a remote API, or a hosted generation service, Picteus\nshould provide one place where AI creators can collect their images, recipes, metadata, and lineage. The objective is\nnot to make creators reorganize their work around Picteus, but to make Picteus the coherent home for the work they\nalready produce across different tools."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"collaboration-with-local-and-remote-ai-systems",children:"Collaboration with local and remote AI systems"}),"\n",(0,i.jsx)(t.p,{children:"The future of AI-assisted image work will probably combine locally running systems with larger online services rather\nthan choosing only one of them. Local models are well suited to specialized processing, lightweight or high-frequency\ntasks, and data that should not leave the user's computer. They can provide responsive enrichment, private analysis, and\nreliable operation without depending on a remote service or a large amount of network bandwidth."}),"\n",(0,i.jsx)(t.p,{children:"Online AI systems, by contrast, can provide access to larger models, more extensive infrastructure, and richer\nprocessing capabilities that may require more memory or computation than a local machine can provide. They can scale on\ndemand and offer services that complement the specialized processing performed locally."}),"\n",(0,i.jsxs)(t.p,{children:["Picteus aims to make collaboration between these systems smooth. It should coordinate their contributions, preserve the\ncontext of each operation, and expose their results through the same image entities and facets. The platform can\ndelegate processing to the already vibrant ecosystem of local AI runtimes and brokers, including tools such as Ollama\nand ",(0,i.jsx)(t.code,{children:"llama.cpp"}),", while also connecting to remote APIs and hosted applications. This mixed model lets users choose where\neach operation should run according to privacy, latency, cost, availability, and processing requirements."]}),"\n",(0,i.jsx)(t.p,{children:"The role of Picteus is therefore not to replace every AI service. It is to provide the orchestration, capture,\nnormalization, and user experience that allow many different services and applications to work together around one\ncorpus of image assets."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"a-platform-for-industrialized-image-work",children:"A platform for industrialized image work"}),"\n",(0,i.jsx)(t.p,{children:"Picteus is not just a personal utility. It is designed for scale and repeatability. In industrial settings, image assets\nare often produced by multiple contributors, multiple models, multiple pipelines, and multiple tools. A platform that\nmerely stores files is not enough; it must keep track of operations, provenance, and semantics."}),"\n",(0,i.jsx)(t.p,{children:"The platform therefore aims to provide:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"a normalized asset model for images and their attached facets ;"}),"\n",(0,i.jsx)(t.li,{children:"structured data about contributors, generation recipes, and transformations ;"}),"\n",(0,i.jsx)(t.li,{children:"search across metadata, tags, features, and embeddings ;"}),"\n",(0,i.jsx)(t.li,{children:"reproducible workflows for image processing and augmentation ;"}),"\n",(0,i.jsx)(t.li,{children:"a way to connect multiple AI services without forcing them into a single fixed stack ;"}),"\n",(0,i.jsx)(t.li,{children:"a user interface that helps humans reason about the corpus instead of only browsing raw assets."}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"This model is useful for teams working with generative AI, content pipelines, media archives, training-data curation,\nvisual research, and product design. It is also useful for individual users who need a disciplined way to work with\nlarge image collections without losing context."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"api-first-and-ux-first",children:"API-first and UX-first"}),"\n",(0,i.jsx)(t.p,{children:"Picteus is intentionally API-first. The back-end exposes a formal web services API, which makes the platform\nprogrammable and integrable. This matters because a modern asset platform cannot live only inside a single interface. It\nmust be able to be orchestrated by tools, scripts, automation pipelines, AI agents, and extension runtimes."}),"\n",(0,i.jsx)(t.p,{children:"At the same time, Picteus invests heavily in a strong user experience. The platform is designed to be usable directly by\npeople who need to inspect, annotate, search, curate, and reason about images. The UX is not a thin layer on top of a\ndatabase; it is part of the platform's core idea. Rich browsing, contextual actions, facets-based filtering, and\nstructured workflows make image intelligence visible and actionable."}),"\n",(0,i.jsx)(t.p,{children:"The combination of API-first architecture and a powerful UX gives Picteus its true character: it is both a system for\nautomation and a system for human understanding."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"normalized-entities-and-formal-contracts",children:"Normalized entities and formal contracts"}),"\n",(0,i.jsx)(t.p,{children:"One of the platform's strongest strategic choices is its use of normalized entities and formal contracts. Images,\nrepositories, collections, features, tags, embeddings, and extensions all sit within a coherent model. These entities\nare not ad hoc or loosely coupled; they are defined by meaningful interfaces and schema constraints."}),"\n",(0,i.jsx)(t.p,{children:"This makes the platform more stable as it grows. It also makes it easier for extensions, SDKs, and AI agents to work\nwith the system without reverse-engineering hidden assumptions. The platform can expose clear contracts and let tools\nbuild on them predictably."}),"\n",(0,i.jsx)(t.p,{children:"This is part of the reason the SDKs and extension model matter so much. They do not just provide convenience; they\ncreate a durable ecosystem. A given capability can be implemented once, reused often, and extended without creating\nuncontrolled divergence across the application."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"extensions-as-the-path-to-adaptability",children:"Extensions as the path to adaptability"}),"\n",(0,i.jsx)(t.p,{children:"The extension model is central to Picteus. Extensions provide a way to augment the application's capabilities without\naltering the core platform for everyone. They can add commands, workflows, custom processing logic, new UI elements, and\nnew integrations with external tools."}),"\n",(0,i.jsx)(t.p,{children:"This is where the platform's true ambition becomes obvious: Picteus is designed to be shaped by the people who use it. A\nplatform with a fixed set of features can address only a subset of real-world workflows. Scientific teams, creative\nstudios, local AI enthusiasts, and domain-specific operators all work differently. There is no single default workflow\nthat fits everyone."}),"\n",(0,i.jsx)(t.p,{children:"Extensions allow the community to respond to that reality. They make the platform more modular, more adaptive, and more\nuseful in practice. They let users add functionality where they need it rather than waiting for a broad product roadmap\nto catch up."}),"\n",(0,i.jsx)(t.p,{children:"This is also a strong fit for the rise of efficient AI coding agents. These tools lower the cost of generating,\nrefining, and testing code. They are no longer just assistants for narrow programming tasks; they are increasingly\ncapable of producing working scaffolding, implementing small feature additions, and iterating on a functional design."}),"\n",(0,i.jsx)(t.p,{children:"The result is a new possibility: a user may not need to become a full-time software engineer in order to shape a local\napplication around their own image workflows. With the right contracts and interfaces, a user can ask an AI agent to\ngenerate a suitable extension, validate it in context, and install it into Picteus. This changes the cost structure of\ncustomization."}),"\n",(0,i.jsx)(t.p,{children:"The vision is therefore not that users must write code manually. The vision is that the platform should be extendable\nenough that AI-assisted construction can become the default path for creating domain-specific features, user\nexperiences, and operational workflows."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"a-user-specific-platform-not-a-one-fits-all-product",children:"A user-specific platform, not a one-fits-all product"}),"\n",(0,i.jsx)(t.p,{children:"There are too many different image workflows to believe that a single monolithic product can satisfy all needs.\nGenerative image production, media archiving, annotation pipelines, data curation, aesthetic evaluation, automated\ntagging, visual similarity research, and remote inference all impose different operational requirements."}),"\n",(0,i.jsx)(t.p,{children:"The future of this kind of platform is therefore not a single fixed interface for everyone. It is a flexible platform\nwhose behavior can be shaped by the user and by the ecosystem around it."}),"\n",(0,i.jsx)(t.p,{children:"This is why the platform should be understood as a general-purpose image operating environment. It should provide a\nstable foundation while allowing the user to install, configure, and evolve the exact capabilities they need. That is\nthe real meaning of flexibility in a domain as broad as image processing and AI-assisted creation."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"the-direction-of-the-ecosystem",children:"The direction of the ecosystem"}),"\n",(0,i.jsx)(t.p,{children:"Picteus is naturally aligned with the broader direction of modern software: extensible platforms, plugin ecosystems, and\ncomposable toolchains. This model often scales better than trying to embed every feature in the core product itself. The\noperating system analogy is useful here."}),"\n",(0,i.jsx)(t.p,{children:"An operating system does not try to do everything directly. It provides stable primitives, a process model, user input,\ncommunication, and a way for other software to integrate. Picteus aims to do something similar for image assets and\nAI-driven workflows: provide a reliable substrate for data, processing, and interaction while allowing specialized\nsoftware to plug in and extend it."}),"\n",(0,i.jsx)(t.p,{children:"The next obvious step in this direction is a marketplace of extensions. Such a marketplace would let users discover,\ninstall, and update a wide range of capabilities: filters, AI models, tagging pipelines, generation tools, connectors to\nexternal services, feature evaluators, and visual tooling. It would also enable a community model where individual users\ncan publish their own extensions for others to reuse."}),"\n",(0,i.jsx)(t.p,{children:"This would turn Picteus from a single application into an ecosystem for image operations. The result would be a richer\nand more durable platform, where the software does not just serve one workflow but supports an open set of complementary\nworkflows."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"why-the-vision-is-realistic-now",children:"Why the vision is realistic now"}),"\n",(0,i.jsx)(t.p,{children:"This is not a fantasy. The building blocks are increasingly available:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"strong local-first application architecture ;"}),"\n",(0,i.jsx)(t.li,{children:"formal, schema-driven API contracts ;"}),"\n",(0,i.jsx)(t.li,{children:"typed SDKs for extension developers ;"}),"\n",(0,i.jsx)(t.li,{children:"AI coding tools that can generate useful software scaffolding ;"}),"\n",(0,i.jsx)(t.li,{children:"a user need for highly personalized workflows rather than generic one-size-fits-all interfaces ;"}),"\n",(0,i.jsx)(t.li,{children:"the desire to integrate locally running and remote AI services without forcing them into a single vendor stack."}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"The platform is already aligned with this direction. What remains is to make it more visible, more discoverable, and\nmore openly community-driven. The ecosystem can grow from a core of reliable primitives into a thriving library of\ncurated extensions and specialized workflows."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"closing-view",children:"Closing view"}),"\n",(0,i.jsx)(t.p,{children:"Picteus can be seen as a practical answer to a simple but profound problem: image work has become too rich, too\ndata-intensive, and too AI-driven to remain locked in a single static application model."}),"\n",(0,i.jsx)(t.p,{children:"The future is a platform that is open, extensible, local-first, and deeply programmable, while remaining elegant enough\nfor human users to operate. Picteus is already moving in that direction."}),"\n",(0,i.jsx)(t.p,{children:"Its success will come from making that extensibility visible, reliable, and community-led \u2014 so that each user can shape\nthe application around their own workflow, while the ecosystem as a whole benefits from shared capabilities and mutual\nreuse."})]})}function h(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,a){a.d(t,{R:()=>o,x:()=>r});var n=a(6540);const i={},s=n.createContext(i);function o(e){const t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);